package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var reader = bufio.NewReader(os.Stdin)

func readLn() string {
	line, _ := reader.ReadString('\n')
	return strings.TrimRight(line, "\r\n")
}

func readInt() int {
	n, _ := strconv.Atoi(readLn())
	return n
}

func readStrings() []string {
	return strings.Split(readLn(), " ")
}

func readInts() []int {
	strs := readStrings()
	ints := make([]int, len(strs))
	for i, s := range strs {
		ints[i], _ = strconv.Atoi(s)
	}
	return ints
}

func findLissPos() int {
	stones := readLn()
	instructions := readLn()
	curPos := 0
	for i := 0; i < len(instructions); i++ {
		if stones[curPos] == instructions[i] {
			curPos++
		}
	}

	curPos++

	return curPos
}

func main() {
	fmt.Print(findLissPos())
}
